typedef struct {
    int value;
} Item;

Item d = { 42 };
Item* p_valid = &d;
Item* p_null = NULL;

// Safe retrieval: Returns value if not NULL, otherwise default (0)
int safe_read_ok = (p_valid != NULL) ? p_valid->value : 0;

// Safe retrieval: Handles the potential NULL pointer
int safe_read_fail = (p_null != NULL) ? p_null->value : -1;
